-- Katalog seed — catalog_data JSON'larından scripts/seed-catalog.ts ile üretildi.
-- Yeniden üretmek için: npx tsx scripts/seed-catalog.ts --kinds wedge_socket,load_cell --out 20260824000008_balance_sockets_loadcells
-- Toplam 30 ürün.

-- Bu türler tamamen katalog dosyalarından üretilir; eski satırlar bırakılmaz.
delete from public.cat_equipment where kind in ('wedge_socket', 'load_cell');


on conflict (key) do update set value = excluded.value, updated_at = now();
